void nf_pc_world_gpu_close(NFPCWorldGPU*g){if(!g)return;if(g->owner!=GetCurrentThreadId()){error("GPU close on wrong thread");return;}HDC dc=wglGetCurrentDC();HGLRC old=wglGetCurrentContext();if(g->context&&wglMakeCurrent(g->dc,g->context)){if(g->program&&g->delete_program)g->delete_program(g->program);if(g->fbo&&g->del)g->del(1,&g->fbo);if(g->palette)glDeleteTextures(1,&g->palette);if(g->input)glDeleteTextures(1,&g->input);if(g->target)glDeleteTextures(1,&g->target);wglMakeCurrent(NULL,NULL);}if(g->context)wglDeleteContext(g->context);if(g->dc&&g->window)ReleaseDC(g->window,g->dc);if(g->window)DestroyWindow(g->window);if(old&&old!=g->context)wglMakeCurrent(dc,old);free(g);}

